# counts: 6=15, 8=18, 4=26, 3=5. Frames use colors 8 (frame itself), 4 (frame). Filled with 3 then 6 = sorted ascending by count among noise colors 3,6.
def f(g):
    from collections import Counter
    H,W=len(g),len(g[0]); cnt=Counter(v for r in g for v in r)
    # find frames: solid closed rectangles
    rects=[]
    seen=set()
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c==0 or (i,j) in seen: continue
            # try expand to a rectangle containing this cell as top-left
            for h in range(2,H-i+1):
                for w in range(2,W-j+1):
                    r0,c0=i,j
                    box=[(a,b) for a in range(i,i+h) for b in range(j,j+w)]
                    ok=all(g[a][b]==c for a,b in box)
                    if ok: 
                        seen.add((i,j)); rects.append((c,(r0,c0),(r0+h-1,c0+w-1))); break
                else: continue
                break
    noise_colors=[v for v in cnt if v not in {c for _,_,_ in rects}]
    # sort noise colors ascending by count
    noise_colors.sort(key=lambda c: cnt[c])
    fill={}
    for idx,(c,tl,bottom) in enumerate(rects):
        fill[idx]=noise_colors[idx]
    res=[row[:] for row in g]
    for idx,(c,tl,bottom) in enumerate(rects):
        r0,c0=tl; r1,c1=bottom
        fc=fill[idx]
        for r in range(r0+1,r1):
            for col in range(c0+1,c1):
                if (r-c0+c1-r1)%2==0: res[r][col]=fc
    return res
