def comps(g):
    H,W=len(g),len(g[0])
    cols=set(Counter(v for r in g for v in r))- {0}
    def is_rect(c):
        ps=set((i,j) for i in range(H) for j in range(W) if g[i][j]==c)
        rs=sorted(set(p[0] for p in ps)); cs=sorted(set(p[1] for p in ps))
        perim=2*(rs[-1]-rs[0]+1)+2*(cs[-1]-cs[0]+1)-4
        return len(ps)==perim and all(p[0] in (rs[0],rs[-1]) or p[1] in (cs[0],cs[-1]) for p in ps)
